from typing import Optional

class DownstreamClientFactory:
    def __init__(self):
        self._client: Optional[httpx.AsyncClient] = None

    def __call__(
        self,
        x_tenant_id: str = Header(..., alias="X-Tenant-ID"),
        user: User = Depends(get_current_user)
    ) -> httpx.AsyncClient:
        if self._client is None:
            self._client = httpx.AsyncClient(
                base_url="https://internal-billing.service.local",
                headers={"X-Authenticated-Tenant": x_tenant_id}
            )
        return self._client

get_billing_client = DownstreamClientFactory()
router = APIRouter(prefix="/gateway/billing")

