from fastapi import APIRouter, Depends, HTTPException, Header
import httpx

async def get_scoped_billing_request(
    x_tenant_id: str = Header(..., alias="X-Tenant-ID"),
    user: User = Depends(get_current_user),
    client_pool: ClientPool = Depends(get_shared_client_pool)
):
    if x_tenant_id not in user.accessible_tenant_ids:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized tenant scope")
    return {"tenant_id": x_tenant_id, "http_client": client_pool.client}

router = APIRouter(prefix="/gateway/billing")

@router.get("/payment-methods")
async def retrieve_payment_methods(
    scoped_req: dict = Depends(get_scoped_billing_request, use_cache=False)
):
    client: httpx.AsyncClient = scoped_req["http_client"]
    resp = await client.get(
        "/v1/stored-cards",
        headers={"X-Authenticated-Tenant": scoped_req["tenant_id"]}
    )
    if resp.status_code != 200:
        raise HTTPException(status_code=502, detail="Downstream billing service error")
    return resp.json()
